 bool bindVerifiedFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(8))return false;for(auto r:ranges_)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:ranges_)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin)||!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool start(Kind k){if(!bound_||active())return false;if(k==Kind::VoiceFeedback)voiceFeedback_.emplace();else dspFeedback_.emplace();return true;}bool active()const{return voiceFeedback_||dspFeedback_;}bool awaitingGlobal()const{return dspFeedback_&&dspFeedback_->child()==Q::Child::Global;}bool resumeGlobal(){return awaitingGlobal()&&dspFeedback_->resumeChild();}void reset(){voiceFeedback_.reset();dspFeedback_.reset();voice_.reset();select_.reset();read_.reset();ownsDsp_=false;}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,const ControllerDspTransferRuntime&dsp)const{if(bound_!=&d||!irq.boundTo(d)||!dsp.boundTo(d)||!active()||d.interruptMode2||d.pendingIrqsHigh||irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled)||(dsp.active()&&!ownsDsp_)||awaitingGlobal())return 0;if(ownsDsp_)return dsp.nextClocks(d,irq);return cost(d.lastWrite)+(d.pendingIrqs?1u:0u);}
 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,unsigned budget){if(bound_!=&d||!irq.boundTo(d)||!dsp.boundTo(d))return {0,false,Block::NotBound};if(!active())return {0,false,Block::Inactive};if(d.interruptMode2||d.pendingIrqsHigh)return {0,false,Block::UnsupportedMode};if(irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return {0,false,Block::NeedsInterrupt};if(dsp.active()&&!ownsDsp_)return {0,false,Block::DspBusy};if(awaitingGlobal())return {0,false,Block::Global};if(ownsDsp_){auto r=dsp.advanceBefore(d,irq,budget);if(r.returned){ownsDsp_=false;if(select_)select_->resumeDsp();else if(read_){readWord_=dsp.receivedWord();read_->resumeDsp();}else dspFeedback_->resumeChild(dsp.receivedWord());}return {r.clocks,false,Block::None};}
 auto c=cost(d.lastWrite),arb=d.pendingIrqs?1u:0u;if(!c||budget<c+arb)return {};if(arb)(void)d.read8(0xfffff2);auto begin=d.cycles;bool stackWrite=false;auto history=[](uint32_t a){return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;};auto read=[&](uint32_t a,unsigned n,unsigned end){uint32_t v=0;unsigned total=n==4?6:3;for(unsigned i=0;i<n;++i){d.cycles=begin+end-total+(n==4&&i<2?3:total);d.lastRead=history(a+i);v=(v<<8)|d.readResource(a+i);}return v;};auto write=[&](uint32_t a,uint32_t v,unsigned n,unsigned end){unsigned total=n==4?6:3;for(unsigned i=0;i<n;++i){d.cycles=begin+end-total+(n==4&&i<2?3:total);d.lastWrite=history(a+i);d.writeResource(a+i,uint8_t(v>>(8*(n-i-1))));}};
 if(voice_){V::Credits cr{3,7};voice_->advanceBefore(c,cr,[&](){return read(0xd023,1,c);});if(voice_->complete()){auto a=voice_->address();voice_.reset();voiceFeedback_->resumeChild(a);}}
 else if(select_){stackWrite=select_->stackWrites();select_->advanceBefore(c,read,write);if(select_->awaitingDsp()){if(!dsp.startInvalidate())return {0,false,Block::DspBusy};ownsDsp_=true;}else if(select_->complete()){select_.reset();voiceFeedback_->resumeChild();}}
 else if(read_){auto stage=read_->stage();stackWrite=stage==R::Stage::DispatchRead;R::Credits cr{3,stage==R::Stage::Return?7u:10u};read_->advanceBefore(c,cr,[&](){return uint16_t(read(0xd026,2,c));});if(read_->awaitingDsp()){if(!dsp.startRead(read_->command()))return {0,false,Block::DspBusy};ownsDsp_=true;}else if(read_->complete()){read_.reset();voiceFeedback_->resumeChild(readWord_);}}
 else if(voiceFeedback_){auto stage=voiceFeedback_->stage();stackWrite=stage==S::LookupVoice||stage==S::InvalidateInactive||stage==S::ReadInactive||stage==S::InvalidateActive||stage==S::ReadActive;auto cr=credits(*voiceFeedback_,d.lastWrite);voiceFeedback_->advanceBefore(c,cr,[&](unsigned f){uint32_t a=f==0?0xd0ec:f==1?0xd022:voiceFeedback_->voice()+(f==2?8:10);return read(a,f<2?1:2,c);},[&](unsigned f,uint32_t v){uint32_t a=f==0?0xd023:f==1?0xd0ec:voiceFeedback_->voice()+(f==2||f==3?8:10);write(a,v,f<2?1:f==2?4:2,c);});auto child=voiceFeedback_->child();if(child==T::Child::Voice)voice_.emplace();else if(child==T::Child::Bus)select_.emplace(ControllerVoiceReleaseDspTask::Kind::Select);else if(child==T::Child::Read)read_.emplace(voiceFeedback_->dspAddress());}
 else{auto stage=dspFeedback_->stage();stackWrite=stage==QS::RetainAddress||stage==QS::Read||stage==QS::Write||stage==QS::Global;VoiceFeedbackCredits cr{};dspFeedback_->advanceBefore(c,cr);auto child=dspFeedback_->child();if(child==Q::Child::Read){if(!dsp.startRead(0x802b))return {0,false,Block::DspBusy};ownsDsp_=true;}else if(child==Q::Child::Write){if(!dsp.startWrite(0x802b,0))return {0,false,Block::DspBusy};ownsDsp_=true;}}
 d.cycles=begin+c;d.lastRead=-1;if(stackWrite)d.lastWrite=-1;bool done=(voiceFeedback_&&voiceFeedback_->complete())||(dspFeedback_&&dspFeedback_->complete());if(done){voiceFeedback_.reset();dspFeedback_.reset();}return {c+arb,done,Block::None};}
